3	import { useEffect, useState } from 'react';
4	import type { AdaptResponse, RecipeDetailResponse } from '@/contracts/api';
5	import { Badge, Button, Card } from '@/components/ui';
6	import { AdaptedCard } from './AdaptedCard';
7	import { OriginalCard } from './OriginalCard';
8	
9	export function RecipeDetail({ recipeId }: { recipeId: string }) {
10	  const [detail, setDetail] = useState<RecipeDetailResponse | null>(null);
11	  const [error, setError] = useState<string | null>(null);
12	  const [adapting, setAdapting] = useState(false);
13	  const [adaptError, setAdaptError] = useState<string | null>(null);
14	
15	  useEffect(() => {
16	    let cancelled = false;
17	    fetch(`/api/recipes/${recipeId}`)
18	      .then(async (res) => {
19	        if (cancelled) return;
20	        if (res.status === 404) {
21	          setError('Recipe not found.');
22	          return;
23	        }
24	        if (!res.ok) throw new Error(`Failed to load (${res.status}).`);
25	        setDetail(await res.json());
26	      })
27	      .catch((err: unknown) => {
28	        if (!cancelled) setError(err instanceof Error ? err.message : 'Failed to load.');
29	      });
30	    return () => {
31	      cancelled = true;
32	    };
33	  }, [recipeId]);
34	
35	  const adapt = async () => {
36	    setAdapting(true);
37	    setAdaptError(null);
38	    try {
39	      const res = await fetch(`/api/recipes/${recipeId}/adapt`, {
40	        method: 'POST',
41	        headers: { 'Content-Type': 'application/json' },
42	        body: '{}',
43	      });
44	      if (res.status === 409) {
45	        setAdaptError('Nothing to adapt — you have every ingredient.');
46	        return;
47	      }
48	      if (!res.ok) {
49	        const body = await res.json().catch(() => null);
50	        throw new Error(body?.error?.message ?? "Couldn't find a safe substitution.");
51	      }
52	      const body = (await res.json()) as AdaptResponse;
53	      setDetail((d) => (d ? { ...d, adaptations: [body.adaptation, ...d.adaptations] } : d));
54	    } catch (err) {
55	      setAdaptError(err instanceof Error ? err.message : "Couldn't find a safe substitution.");
56	    } finally {
57	      setAdapting(false);
58	    }
59	  };
60	
61	  if (error) return <p>{error}</p>;
62	  if (!detail) return <p className="text-muted">Loading recipe…</p>;
63	
64	  const { original, matches, adaptations } = detail;
65	  const missing = matches.filter((m) => m.status === 'missing' || m.status === 'insufficient');
66	  const est = detail.nutrition.estimate;
67	  const pub = detail.nutrition.publisher;
68	
69	  return (
70	    <div className="flex flex-col gap-4">
71	      <div>
72	        <h1 className="font-display text-3xl font-semibold">{original.title}</h1>
73	        <p className="mt-1 text-sm text-muted">
74	          {original.servings} servings
75	          {original.times.totalMin != null ? ` · ${original.times.totalMin} min` : ''}
76	        </p>
77	      </div>
78	
79	      <Card>
80	        <div className="text-sm">
81	          ≈ {est.perServing.energyKcal ?? '?'} kcal · {est.perServing.proteinG ?? '?'} g protein per serving{' '}
82	          <span className="text-muted">
83	            (based on {est.basedOn} of {est.total} ingredients)
84	          </span>
85	        </div>
86	        {pub?.energyKcal != null && (
87	          <div className="mt-1 text-sm text-muted">Publisher&apos;s nutrition: {pub.energyKcal} kcal per serving</div>
88	        )}
89	        {est.estimatedFields.length > 0 && (
90	          <details className="mt-1 text-xs text-muted">
91	            <summary>Estimates used</summary>
92	            <ul className="list-disc pl-5">
93	              {est.estimatedFields.map((f, i) => (
94	                <li key={i}>{f}</li>
95	              ))}
96	            </ul>
97	          </details>
98	        )}
99	      </Card>
100	
101	      <OriginalCard recipe={original} matches={matches} recipeId={recipeId} />
102	
103	      {missing.length > 0 && adaptations.length === 0 && (
104	        <div>
105	          <Button variant="secondary" onClick={adapt} disabled={adapting}>
106	            {adapting ? 'Adapting…' : `Adapt for missing ingredients (${missing.length})`}
107	          </Button>
108	          {adaptError && <p className="mt-2 text-sm text-danger">{adaptError}</p>}
109	        </div>
110	      )}
111	      {adaptations.length > 0 && <Badge tone="ai">Showing {adaptations.length} AI adaptation(s) below</Badge>}
112	      {adaptations.map((a) => (
113	        <AdaptedCard key={a.variantId} adaptation={a} siteName={original.source.siteName} />
114	      ))}
115	    </div>
116	  );
117	}
