1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import type { DeductionLine, FinishPreview, FinishResult, UnitDim } from "@/contracts";
5	import { Badge, Button, Dialog } from "@/components/ui";
6	import { ApiRequestError, finishSession, getFinishPreview } from "./api";
7	
8	const UNIT: Record<UnitDim, string> = { mass: "g", volume: "ml", count: "pcs" };
9	const BASIS_LABEL = {
10	  estimate: "≈ estimate",
11	  publisher: "Publisher's nutrition",
12	  low_coverage_estimate: "≈ rough estimate (low coverage)",
13	};
14	
15	type Line = DeductionLine & { checked: boolean; qty: string };
16	
17	/** A line the user can deduct: matched to a pantry item with a known unit. */
18	export const deductible = (l: DeductionLine) =>
19	  l.pantryItemId !== null && l.dim !== null && (l.status === "ok" || l.status === "clamped" || l.status === "unconvertible");
20	
21	export function toLines(p: FinishPreview): Line[] {
22	  return p.deductions.map((d) => ({
23	    ...d,
24	    // Unconvertible lines start unchecked and empty: the user enters the amount ("Adjust manually").
25	    checked: deductible(d) && d.status !== "unconvertible",
26	    qty: d.proposedQtyBase === null || d.status === "unconvertible" ? "" : String(Math.round(d.proposedQtyBase * 10) / 10),
27	  }));
28	}
29	
30	/** SPEC F14 dialog: servings, editable deduction preview, editable nutrition, one confirm. */
31	export function FinishDialog({
32	  sessionId,
33	  servingsPlanned,
34	  open,
35	  onClose,
36	  onFinished,
37	}: {
38	  sessionId: string;
39	  servingsPlanned: number;
40	  open: boolean;
41	  onClose: () => void;
42	  /** null = the session was already finished elsewhere (409). */
43	  onFinished: (r: FinishResult | null) => void;
44	}) {
45	  const [servingsCooked, setServingsCooked] = useState(servingsPlanned);
46	  const [servingsEaten, setServingsEaten] = useState(1);
47	  // The plan remembers which servings count it was built for; Confirm needs it to match.
48	  const [plan, setPlan] = useState<{ servings: number; preview: FinishPreview } | null>(null);
49	  const [lines, setLines] = useState<Line[]>([]);
50	  const [kcal, setKcal] = useState("");
51	  const [protein, setProtein] = useState("");
52	  const [error, setError] = useState<string | null>(null);
53	  const [saving, setSaving] = useState(false);
54	
55	  // Re-plan whenever servings cooked changes (debounced). Line edits reset with the new plan.
56	  useEffect(() => {
57	    if (!open) return;
58	    let cancelled = false;
59	    const t = setTimeout(() => {
60	      getFinishPreview(sessionId, servingsCooked)
61	        .then((p) => {
62	          if (cancelled) return;
63	          setPlan({ servings: servingsCooked, preview: p });
64	          setLines(toLines(p));
65	          setKcal(String(Math.round(p.suggestedLogPerServing.kcal)));
66	          setProtein(String(Math.round(p.suggestedLogPerServing.proteinG)));
67	          setError(null);
68	        })
69	        .catch((e: Error) => !cancelled && setError(`Couldn't load the pantry preview: ${e.message}`));
70	    }, 300);
71	    return () => {
72	      cancelled = true;
73	      clearTimeout(t);
74	    };
75	  }, [open, sessionId, servingsCooked]);
76	
77	  const update = (i: number, patch: Partial<Line>) => setLines((ls) => ls.map((l, j) => (j === i ? { ...l, ...patch } : l)));
78	
79	  const kcalN = Number(kcal);
80	  const proteinN = Number(protein);
81	  const nutritionValid = kcal !== "" && protein !== "" && kcalN >= 0 && proteinN >= 0;
82	  const preview = plan?.servings === servingsCooked ? plan.preview : null; // null while re-planning or after a failed load
83	  const valid = preview !== null && (servingsEaten === 0 || nutritionValid);
84	
85	  async function confirm() {
86	    if (!preview || !valid) return;
87	    setSaving(true);
88	    setError(null);
89	    const s = preview.suggestedLogPerServing;
90	    const edited = kcalN !== Math.round(s.kcal) || proteinN !== Math.round(s.proteinG);
91	    try {
92	      const result = await finishSession(sessionId, {
93	        servingsCooked,
94	        servingsEaten,
95	        deductions: lines
96	          .filter((l) => l.checked && l.pantryItemId && Number(l.qty) > 0)
97	          .map((l) => ({ pantryItemId: l.pantryItemId!, qtyBase: Number(l.qty) })),
98	        perServingOverride: servingsEaten > 0 && edited ? { kcal: kcalN, proteinG: proteinN } : undefined,
99	      });
100	      onFinished(result);
101	    } catch (e) {
102	      if (e instanceof ApiRequestError && e.status === 409) return onFinished(null);
103	      setSaving(false);
104	      setError("Couldn't save. Nothing was changed, so you can try again.");
105	    }
106	  }
107	
108	  return (
109	    <Dialog open={open} onClose={onClose} title="Finish cooking" className="theme-cook max-h-[90dvh] w-[min(44rem,calc(100vw-2rem))]">
110	      <div className="grid gap-4 sm:grid-cols-2">
111	        <Stepper
112	          label="Servings cooked"
113	          value={servingsCooked}
114	          min={1}
115	          onChange={(n) => {
116	            setServingsCooked(n);
117	            setServingsEaten((e) => Math.min(e, n)); // can't eat more than was cooked (server enforces too)
118	          }}
119	        />
120	        <Stepper label="Servings you ate" value={servingsEaten} min={0} max={servingsCooked} onChange={setServingsEaten} />
121	      </div>
122	
123	      <h3 className="mt-6 text-lg font-semibold">Remove from pantry</h3>
124	      {!preview && !error && <p className="mt-2 text-muted">Working out what you used…</p>}
125	      <ul className="mt-2 divide-y divide-line">
126	        {(preview ? lines : []).map((l, i) => (
127	          <li key={`${l.ingredientRaw}-${i}`} className="flex flex-wrap items-center gap-3 py-3">
128	            {deductible(l) ? (
129	              <>
130	                <label className="flex min-w-0 flex-1 items-center gap-3">
131	                  <input
132	                    type="checkbox"
133	                    className="size-6 shrink-0 accent-[var(--accent)]"
134	                    checked={l.checked}
135	                    onChange={(e) => update(i, { checked: e.target.checked })}
136	                  />
137	                  <span className="min-w-0">
138	                    <span className="block">{l.status === "unconvertible" ? `${l.pantryItemName ?? l.ingredientRaw} (${l.ingredientRaw})` : l.display}</span>
139	                    {l.status === "clamped" && <Badge tone="warn">Only {l.availableQtyBase} {UNIT[l.dim!]} left</Badge>}
140	                    {l.status === "unconvertible" && <Badge tone="warn">Adjust manually</Badge>}
141	                  </span>
142	                </label>
143	                <label className="flex items-center gap-2">
144	                  <span className="sr-only">Amount of {l.pantryItemName ?? l.ingredientRaw} to remove</span>
145	                  <input
146	                    type="number"
147	                    inputMode="decimal"
148	                    min={0}
149	                    max={l.availableQtyBase ?? undefined}
150	                    step="any"
151	                    value={l.qty}
152	                    onChange={(e) => update(i, { qty: e.target.value, checked: Number(e.target.value) > 0 })}
153	                    className="w-24 rounded-lg border border-line bg-surface px-3 py-2 text-right"
154	                  />
155	                  <span className="w-8 text-muted">{UNIT[l.dim!]}</span>
156	                </label>
157	              </>
158	            ) : (
159	              <span className="min-w-0 flex-1 text-muted">
160	                {l.ingredientRaw}{" "}
161	                <Badge>{l.status === "staple" ? "Staple" : l.status === "no_match" ? "Not in pantry" : "Adjust manually"}</Badge>
162	              </span>
163	            )}
164	          </li>
165	        ))}
166	      </ul>
167	
168	      {preview && servingsEaten > 0 && (
169	        <>
170	          <h3 className="mt-6 flex flex-wrap items-center gap-2 text-lg font-semibold">
171	            Nutrition per serving <Badge tone="ai">{BASIS_LABEL[preview.suggestedLogPerServing.basis]}</Badge>
172	          </h3>
173	          <div className="mt-2 grid grid-cols-2 gap-4">
174	            <NumberField label="kcal" value={kcal} onChange={setKcal} />
175	            <NumberField label="Protein (g)" value={protein} onChange={setProtein} />
176	          </div>
177	          {nutritionValid && (
178	            <p className="mt-2 text-sm text-muted">
179	              Logs {servingsEaten} serving{servingsEaten === 1 ? "" : "s"} · {Math.round(kcalN * servingsEaten)} kcal ·{" "}
180	              {Math.round(proteinN * servingsEaten)} g protein
181	            </p>
182	          )}
183	        </>
184	      )}
185	      {servingsEaten === 0 && <p className="mt-6 text-muted">Nothing will be logged as eaten. The pantry is still updated.</p>}
186	
187	      {error && (
188	        <p role="alert" className="mt-4 text-danger">
189	          {error}
190	        </p>
191	      )}
192	
193	      <div className="mt-6 flex flex-wrap justify-end gap-3">
194	        <Button size="lg" variant="ghost" onClick={onClose}>
195	          Keep cooking
196	        </Button>
197	        <Button size="lg" onClick={confirm} disabled={!valid || saving}>
198	          {saving ? "Saving…" : "Confirm"}
199	        </Button>
200	      </div>
201	    </Dialog>
202	  );
203	}
