205	function Stepper({ label, value, min, max, onChange }: { label: string; value: number; min: number; max?: number; onChange: (n: number) => void }) {
206	  return (
207	    <div>
208	      <span className="text-sm text-muted">{label}</span>
209	      <div className="mt-1 flex items-center gap-2">
210	        <Button size="lg" variant="secondary" aria-label={`Fewer: ${label}`} onClick={() => onChange(Math.max(min, value - 1))} disabled={value <= min}>
211	          −
212	        </Button>
213	        <span className="w-12 text-center text-2xl font-semibold" aria-live="polite">
214	          {value}
215	        </span>
216	        <Button size="lg" variant="secondary" aria-label={`More: ${label}`} onClick={() => onChange(value + 1)} disabled={max !== undefined && value >= max}>
217	          +
218	        </Button>
219	      </div>
220	    </div>
221	  );
222	}
223	
224	function NumberField({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
225	  return (
226	    <label className="block">
227	      <span className="text-sm text-muted">{label}</span>
228	      <input
229	        type="number"
230	        inputMode="decimal"
231	        min={0}
232	        value={value}
233	        onChange={(e) => onChange(e.target.value)}
234	        className="mt-1 w-full rounded-lg border border-line bg-surface px-3 py-2 text-lg"
235	      />
236	    </label>
237	  );
238	}
