3	// SPEC F15: a progress ring against a goal. With no goal set it shows the total only.
4	
5	const SIZE = 132;
6	const STROKE = 10;
7	const RADIUS = (SIZE - STROKE) / 2;
8	const CIRCUMFERENCE = 2 * Math.PI * RADIUS;
9	
10	export function Ring({ label, value, goal, unit }: { label: string; value: number; goal: number | null; unit: string }) {
11	  const shown = Math.round(value);
12	  const center = (
13	    <>
14	      <span className="font-display text-2xl font-semibold tabular-nums">{shown}</span>
15	      <span className="text-xs text-muted">{unit}</span>
16	    </>
17	  );
18	
19	  if (goal == null) {
20	    return (
21	      <div className="grid justify-items-center gap-2">
22	        <div className="grid h-[132px] w-[132px] place-content-center justify-items-center">{center}</div>
23	        <p className="text-sm font-semibold">{label}</p>
24	        <p className="text-xs text-muted">No goal set</p>
25	      </div>
26	    );
27	  }
28	
29	  const over = Math.round(value - goal);
30	  return (
31	    <div className="grid justify-items-center gap-2">
32	      <div className="relative h-[132px] w-[132px]">
33	        <svg viewBox={`0 0 ${SIZE} ${SIZE}`} role="img" aria-label={`${label}: ${shown} of ${goal} ${unit}`} className="-rotate-90">
34	          <circle cx={SIZE / 2} cy={SIZE / 2} r={RADIUS} fill="none" stroke="var(--line)" strokeWidth={STROKE} />
35	          {value > 0 && (
36	            <circle
37	              cx={SIZE / 2}
38	              cy={SIZE / 2}
39	              r={RADIUS}
40	              fill="none"
41	              stroke={CHART_COLOR}
42	              strokeWidth={STROKE}
43	              strokeLinecap="round"
44	              strokeDasharray={CIRCUMFERENCE}
45	              strokeDashoffset={ringOffset(CIRCUMFERENCE, value, goal)}
46	            />
